export function distanceMiles(a,b){const r=Math.PI/180;const x=Math.sin((b.lat-a.lat)*r/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin((b.lon-a.lon)*r/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(x),Math.sqrt(Math.max(0,1-x)))}
export function summary(s,now=Date.now()){if(!s)return {income:0,miles:0,cost:0,remaining:0,hours:0,hourly:0};const miles=s.endOdo==null?s.gpsMiles:Math.max(0,s.endOdo-s.startOdo);const income=s.income??s.jobs.reduce((n,j)=>n+j.fare,0);const cost=miles*s.cab.rate+s.cab.fixed+(s.extra||0);const hours=Math.max(0,((s.end||now)-s.start)/3600000-(s.breakMinutes||0)/60);return {income,miles,cost,remaining:income-cost,hours,hourly:hours?(income-cost)/hours:0}}
export function validateEnd(s,{endOdo,income,extra,breakMinutes},now=Date.now()){if(![endOdo,income,extra,breakMinutes].every(Number.isFinite)||Math.min(income,extra,breakMinutes)<0)return 'Enter valid, non-negative amounts.';if(endOdo<s.startOdo)return 'Ending mileage must be at least the starting mileage.';if(breakMinutes>Math.floor((now-s.start)/60000))return 'Break time cannot exceed the shift duration.';return null}
